const D = { energy:.6, scale:1, density:.5, speed:1, hue:46, x:.42, y:.5, trains:.5, style:'tiled', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, HU = ((P.hue%360)+360)%360;
const wire = (sty === 'blueprint'), paper = (sty === 'engraving');

// ---- the camera creeps down an endless platform; bays keyed on ABSOLUTE index
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z = (S.z||0) + dt * P.speed * (.10 + .12*K.intensity + .11*P.energy);
const bsm = (S.bm = (S.bm||0)*.84 + (A.bass||0)*.16);
const gl = (.44 + .56*P.energy) * (.55 + .5*K.intensity) + bsm*.26;

const dA = .55*Math.sin(K.t*.41) + .30*Math.sin(K.t*.97+1.7) + .17*Math.sin(K.t*1.63+.4);
const dB = .50*Math.sin(K.t*.53+2.1) + .32*Math.sin(K.t*1.19+.9) + .20*Math.sin(K.t*2.29+2.6);
const dC = .60*Math.sin(K.t*.089) + .40*Math.sin(K.t*.211+1.1);

const BS = u*.62;                                    // bay pitch, fixed => P.scale is not a no-op
const PW = u*.58*P.scale, TW = u*.52*P.scale, CH = u*.66*P.scale, PH = u*.13*P.scale;
const NB = Math.round(6 + cl(P.density,0,1)*6);
const camZ = S.z*BS;
const camX = -PW*.55 + u*.012*dB*P.energy;
const camY = -(PH + u*.29 + u*.022*dC*P.energy);
const yaw = .030*dA*P.energy + .018*Math.sin(K.t*.137+2.4);
const ca = Math.cos(yaw), sa = Math.sin(yaw);
const f = u*1.05, NEAR = u*.07;
const vcx = cl(P.x,.15,.85)*width, vcy = cl(P.y,.3,.75)*height;
const base = Math.floor(S.z), trav = S.z - base;
const ZT = (base + NB - trav)*BS;                    // tunnel mouth holds station at the VP

// ---- train events on a slowly-warped schedule -> never the same 8s apart -----
const TP = 34 + 26*(1 - cl(P.trains,0,1));
const tph = K.t/TP + .19*Math.sin(K.t*.0193) + .08*Math.sin(K.t*.0071+1.1);
const evi = Math.floor(tph), fph = tph - evi;
const run = fph < .30 && P.trains > .02;
const tz = camZ + BS*((NB+2.5) - (fph/.30)*(NB+11));  // nose position: tunnel -> past us
const TL = BS*3.4;                                    // train length

// ---- projection --------------------------------------------------------------
const AX = new Float64Array(24), AY = new Float64Array(24), AZ = new Float64Array(24);
const BX = new Float64Array(34), BY = new Float64Array(34);
function poly(v){
  const n = v.length/3;
  for (let i=0;i<n;i++){
    const X = v[i*3]-camX, Y = v[i*3+1]-camY, Z = v[i*3+2]-camZ;
    AX[i] = X*ca - Z*sa; AY[i] = Y; AZ[i] = X*sa + Z*ca;
  }
  let m = 0;
  for (let i=0;i<n;i++){
    const j = (i+1)%n, az = AZ[i], bz = AZ[j], ai = az>NEAR, bi2 = bz>NEAR;
    if (ai){ BX[m] = vcx + f*AX[i]/az; BY[m] = vcy + f*AY[i]/az; m++; }
    if (ai !== bi2){
      const tt = (NEAR-az)/(bz-az);
      BX[m] = vcx + f*(AX[i]+(AX[j]-AX[i])*tt)/NEAR;
      BY[m] = vcy + f*(AY[i]+(AY[j]-AY[i])*tt)/NEAR; m++;
    }
  }
  if (m < 3) return false;
  beginShape(); for (let i=0;i<m;i++) vertex(BX[i], BY[i]); endShape(CLOSE);
  return true;
}
function pt2(X,Y,Z){
  const dx = X-camX, dy = Y-camY, dz = Z-camZ;
  const rz = dx*sa + dz*ca;
  if (rz <= NEAR) return null;
  return [vcx + f*(dx*ca - dz*sa)/rz, vcy + f*dy/rz, rz];
}

// ---- tone tables -------------------------------------------------------------
function mixc(c,d,t){ const dh = ((d[0]-c[0])%360+540)%360-180;
  return [c[0]+dh*t, c[1]+(d[1]-c[1])*t, c[2]+(d[2]-c[2])*t]; }
const HAZE = paper ? [40, 6, 90] : wire ? [212, 58, 20] : sty === 'noir' ? [0,0,26]
           : sty === 'sodium' ? [28, 46, 22] : [(HU+150)%360, 12, 26];
const fogA = (paper||wire) ? .28 : .70;
// v 0..1 modelled luminance for GRIMY TILE / concrete
function tone(v, tv){
  if (paper) return [40, 5 + 4*tv, cl(97 - 50*(1-v), 42, 97)];
  if (wire)  return [212, 60, cl(11 + 10*v, 7, 30)];
  if (sty === 'noir')   return [0, 0, cl(3 + 88*Math.pow(v,1.5), 2, 97)];
  if (sty === 'sodium') return [cl(26 + 10*tv, 18, 42), cl(56 - 24*v, 8, 70), cl(4 + 74*v, 3, 92)];
  return [(HU + 132 - 96*v)%360, cl(16 - 10*v + 8*tv, 2, 26), cl(8 + 78*v, 4, 95)];
}
function ink(a){
  if (wire) stroke(190, 30, 100, a);
  else if (paper) stroke(30, 20, 14, a);
  else if (sty === 'noir') stroke(0, 0, 92, a*.4);
  else stroke((HU+140)%360, 10, 82, a*.32);
}
const LTH = sty === 'sodium' ? 30 : sty === 'noir' ? 0 : (HU+2)%360;   // lamp hue

// ---- ceiling / far volume / track bed (banded) --------------------------------
noStroke();
const NBD = 28;
for (let i=0;i<NBD;i++){
  const s = i/(NBD-1), c = tone(.05 + .16*s, fr(i*3.1));
  fill(c[0], c[1], cl(c[2] + (fr(i*5.7)-.5)*1.6, 0, 100));
  rect(0, s*vcy - 1.5, width, vcy/NBD + 3);
}
for (let i=0;i<NBD;i++){
  const s = i/(NBD-1), c = tone(.20 - .09*s, fr(i*7.7+11));
  fill(c[0], c[1], cl(c[2] + (fr(i*9.1+3)-.5)*2.0, 0, 100));
  rect(0, vcy + s*(height-vcy) - 1.5, width, (height-vcy)/NBD + 3);
}

// ---- tunnel mouth: an arch of true black at the vanishing point ---------------
const arch = [];
for (let i=0;i<=12;i++){
  const a2 = Math.PI*i/12;
  arch.push(TW*.5 + TW*.46*Math.cos(a2), -TW*.44*Math.sin(a2) - PH*.2, ZT);
}
arch.push(TW*.04, 0, ZT, TW*.96, 0, ZT);
if (wire){ noFill(); ink(70); } else { noStroke(); fill(paper?42:0, paper?4:0, paper?18:2, 100); }
poly(arch);

// ---- far wall (X = TW): tile bands + seams — texture, never a flat fill --------
const zA = base*BS, zB = ZT;
const NR = 6;
for (let r=0; r<NR; r++){
  const y0 = -CH + (CH*(r/NR)), y1 = -CH + (CH*((r+1)/NR));
  const rv = .30 + .30*(r/NR) + .10*fr(r*13.1);
  const c = mixc(tone(rv*(.5+.55*gl), fr(r*3.7)), HAZE, .30*fogA);
  if (wire){ noFill(); ink(46); } else { noStroke(); fill(c[0], c[1], c[2], 100); }
  poly([TW, y0, zA, TW, y1, zA, TW, y1, zB, TW, y0, zB]);
}
strokeWeight(Math.max(1, u*.0012));
ink(paper ? 34 : 30); noFill();
for (let r=1; r<NR; r++){ const yy = -CH + CH*(r/NR); poly([TW, yy, zA, TW, yy, zB]); }
for (let k=base; k<=base+NB; k++){
  for (let h2=0; h2<2; h2++){
    const zz = (k + h2*.5)*BS;
    if (zz < camZ + NEAR || zz > ZT) continue;
    poly([TW, -CH, zz, TW, 0, zz]);
  }
}
// grimed / discoloured tiles, seeded on absolute index
if (!wire && !paper){
  noStroke();
  for (let k=base; k<base+NB; k++){
    for (let q=0;q<2;q++){
      const rr = fr(k*17.7 + q*4.3);
      if (rr > .46) continue;
      const r2 = Math.floor(rr*NR*2.4)%NR;
      const y0 = -CH + CH*(r2/NR), y1 = -CH + CH*((r2+1)/NR);
      const z0 = (k + .5*q)*BS, z1 = z0 + BS*.5;
      if (z1 < camZ + NEAR) continue;
      const c = mixc(tone(.16 + .22*rr, rr), HAZE, .3*fogA);
      fill(c[0], cl(c[1]+16*rr,0,60), c[2]*.72, 100);
      poly([TW, y0, z0, TW, y1, z0, TW, y1, z1, TW, y0, z1]);
    }
  }
}

// ---- track bed, sleepers, rails ----------------------------------------------
if (!wire){
  const c = mixc(tone(.10, .4), HAZE, .25*fogA);
  noStroke(); fill(c[0], c[1], c[2], 100);
  poly([0, 0, base*BS, TW, 0, base*BS, TW, 0, ZT, 0, 0, ZT]);
  for (let k=base*2; k<(base+NB)*2; k++){
    const z0 = k*BS*.5 + BS*.10, z1 = z0 + BS*.18;
    if (z1 < camZ + NEAR) continue;
    const hz = cl((z0-camZ)/(NB*BS), 0, 1);
    const c2 = mixc(tone(.06 + .08*fr(k*5.1), fr(k*2.3)), HAZE, hz*fogA);
    fill(c2[0], c2[1], c2[2], 100);
    poly([TW*.16, 0, z0, TW*.86, 0, z0, TW*.86, 0, z1, TW*.16, 0, z1]);
  }
}
for (let ri=0; ri<3; ri++){
  const rx = [TW*.26, TW*.70, TW*.92][ri];
  const rw2 = TW*.018;
  const c = mixc(tone(ri===2 ? .30 : .52, .5), HAZE, .34*fogA);
  if (wire){ noFill(); ink(58); } else { noStroke(); fill(c[0], c[1]*.5, c[2], 100); }
  poly([rx-rw2, -u*.006, base*BS, rx+rw2, -u*.006, base*BS, rx+rw2, -u*.006, ZT, rx-rw2, -u*.006, ZT]);
}

// ---- platform slab + edge face + tactile warning strip -------------------------
if (!wire){
  const c = mixc(tone(.26, .5), HAZE, .22*fogA);
  noStroke(); fill(c[0], c[1], c[2], 100);
  poly([-PW, -PH, base*BS, 0, -PH, base*BS, 0, -PH, ZT, -PW, -PH, ZT]);
  const c2 = mixc(tone(.13, .3), HAZE, .22*fogA);
  fill(c2[0], c2[1], c2[2], 100);
  poly([0, -PH, base*BS, 0, 0, base*BS, 0, 0, ZT, 0, -PH, ZT]);
  const c3 = mixc(paper ? [42,10,72] : sty === 'noir' ? [0,0,74] : [48, 74, cl(52 + 34*gl, 20, 96)], HAZE, .3*fogA);
  fill(c3[0], c3[1], c3[2], 100);
  poly([-PW*.14, -PH-1, base*BS, 0, -PH-1, base*BS, 0, -PH-1, ZT, -PW*.14, -PH-1, ZT]);
} else {
  ink(64); noFill();
  poly([-PW, -PH, base*BS, 0, -PH, base*BS, 0, -PH, ZT, -PW, -PH, ZT]);
}
// platform slab joints
ink(paper ? 28 : 26); noFill(); strokeWeight(Math.max(1, u*.0011));
for (let k=base; k<=base+NB; k++){ const zz = k*BS; if (zz > camZ+NEAR) poly([-PW, -PH, zz, 0, -PH, zz]); }

// ---- near wall + per-bay furniture, far -> near --------------------------------
for (let k = base+NB-1; k >= base; k--){
  const z0 = k*BS, z1 = (k+1)*BS;
  if (z1 < camZ + NEAR) continue;
  const hz = cl((z0 - camZ)/(NB*BS), 0, 1);
  const tv = fr(k*31.7);

  // wall panel
  const c = mixc(tone(.28 + .16*tv, tv), HAZE, hz*fogA);
  if (wire){ noFill(); ink(50); } else { noStroke(); fill(c[0], c[1], c[2], 100); }
  poly([-PW, -CH, z0, -PW, -PH, z0, -PW, -PH, z1, -PW, -CH, z1]);
  // dado band — horizontal tonal split so the wall is never one flat fill
  if (!wire){
    const c2 = mixc(tone(.14 + .10*tv, tv), HAZE, hz*fogA);
    noStroke(); fill(c2[0], c2[1], c2[2], 100);
    poly([-PW, -CH*.42, z0, -PW, -PH, z0, -PW, -PH, z1, -PW, -CH*.42, z1]);
  }
  ink(paper ? 32 : 26); noFill();
  poly([-PW, -CH*.42, z0, -PW, -CH*.42, z1]);
  poly([-PW, -CH, z0, -PW, -PH, z0]);

  // advert light-box, seeded on absolute bay index
  if (fr(k*7.3+11) < .44){
    const ah = ((fr(k*19.1)*300)|0);
    const y0 = -CH*.86, y1 = -CH*.46;
    const zz0 = z0 + BS*.14, zz1 = z1 - BS*.14;
    if (wire){ noFill(); ink(72); }
    else {
      noStroke();
      const bv = cl(38 + 52*gl*(.6+.4*Math.sin(K.t*.31 + k*1.7)), 10, 97);
      const ac = mixc(paper ? [40, 8, 88] : sty === 'noir' ? [0,0,bv] : [ah, sty==='sodium'?34:52, bv], HAZE, hz*fogA*.6);
      fill(ac[0], ac[1], ac[2], 100);
    }
    poly([-PW, y0, zz0, -PW, y1, zz0, -PW, y1, zz1, -PW, y0, zz1]);
    if (!wire && !paper && hz < .5){
      push(); blendMode(ADD); noStroke();
      fill(sty==='noir'?0:ah, sty==='noir'?0:30, 100, cl(4 + 8*gl, 0, 18));
      poly([-PW, y0-CH*.06, zz0-BS*.08, -PW, y1+CH*.06, zz0-BS*.08, -PW, y1+CH*.06, zz1+BS*.08, -PW, y0-CH*.06, zz1+BS*.08]);
      pop(); blendMode(BLEND);
    }
  }

  // I-beam pillar standing on the platform
  const px = -PW*.30, pw2 = u*.026*P.scale;
  const a2 = pt2(px, 0, z0 + BS*.5);
  if (a2){
    for (let s2=0; s2<3; s2++){
      const p0 = -1 + 2*s2/3, p1 = -1 + 2*(s2+1)/3, pm = (p0+p1)*.5;
      const lamb = cl(.20 + .82*Math.cos((pm - .55)*1.5), 0, 1);
      const c2 = mixc(tone(cl(lamb*(.42+.5*gl), 0, 1), tv), HAZE, hz*fogA);
      if (wire){ noFill(); ink(54); } else { noStroke(); fill(c2[0], c2[1], c2[2], 100); }
      const rw = f*pw2/a2[2];
      const yb = vcy + f*(-PH - camY)/a2[2], yt = vcy + f*(-CH - camY)/a2[2];
      rect(a2[0] + p0*rw, yt, (p1-p0)*rw + 1.1, yb-yt);
    }
  }

  // ceiling strip light + the pool it throws on the platform
  const alive = fr(k*5.1+3) > .14;
  if (alive && !paper){
    const fl = .60 + .40*Math.sin(K.t*(.7 + fr(k*2.7)*.6) + k*2.1);
    const bv = cl((sty==='sodium'?54:70) + 30*gl*fl, 8, 97);
    if (wire){ noFill(); ink(88); }
    else { noStroke(); fill(LTH, sty==='noir'?0:(sty==='sodium'?40:14), bv, 100); }
    poly([-PW*.72, -CH, z0+BS*.16, -PW*.16, -CH, z0+BS*.16, -PW*.16, -CH, z1-BS*.16, -PW*.72, -CH, z1-BS*.16]);
    if (!wire && hz < .62){
      push(); blendMode(ADD); noStroke();
      fill(LTH, sty==='noir'?0:26, 100, cl(3.4 + 6*gl*fl, 0, 20));
      poly([-PW, -PH, z0-BS*.24, 0, -PH, z0-BS*.24, 0, -PH, z1+BS*.24, -PW, -PH, z1+BS*.24]);
      pop(); blendMode(BLEND);
    }
  }
}

// ---- the train: emerges from the tunnel, runs the well, sweeps past ------------
if (run && !wire){
  const nose = tz, tail = tz + TL;
  const TX0 = TW*.14, TX1 = TW*.86, TY = -TW*.50, hz = cl((nose - camZ)/(NB*BS), 0, 1);
  // headlight bloom lands before the body resolves
  const hl = pt2(TW*.5, TY*.62, nose);
  if (hl){
    push(); blendMode(ADD); noStroke();
    const hb = cl(6 + 16*gl, 0, 26);
    for (let i=4;i>=1;i--){
      fill(sty==='noir'?0:(sty==='sodium'?36:52), sty==='noir'?0:16, 100, hb*(.35+.2*i)*(1-hz*.4));
      ellipse(hl[0], hl[1], f*TW*.5/hl[2]*i*.5, f*TW*.34/hl[2]*i*.5);
    }
    pop(); blendMode(BLEND);
  }
  // flank facing the platform
  const c = mixc(tone(.30 + .22*Math.sin(K.t*.9), .5), HAZE, hz*fogA*.7);
  noStroke(); fill(c[0], cl(c[1]*.7,0,40), c[2], 100);
  poly([TX0, 0, nose, TX0, TY, nose, TX0, TY, tail, TX0, 0, tail]);
  // nose cap
  const c2 = mixc(tone(.44, .5), HAZE, hz*fogA*.7);
  fill(c2[0], c2[1]*.6, c2[2], 100);
  poly([TX0, 0, nose, TX1, 0, nose, TX1, TY, nose, TX0, TY, nose]);
  // lit windows streaking past
  for (let w2=0; w2<7; w2++){
    const zz = nose + TL*(.10 + .12*w2);
    const bv = cl(56 + 38*gl*(.7+.3*Math.sin(K.t*4.1 + w2)), 12, 98);
    fill(sty==='noir'?0:(sty==='sodium'?42:56), sty==='noir'?0:22, bv, 100);
    poly([TX0, TY*.72, zz, TX0, TY*.30, zz, TX0, TY*.30, zz+TL*.075, TX0, TY*.72, zz+TL*.075]);
  }
  // spill on the far wall
  push(); blendMode(ADD); noStroke();
  fill(sty==='noir'?0:(HU+2)%360, sty==='noir'?0:20, 100, cl(2.6 + 4.4*gl, 0, 12));
  poly([TW, -CH*.7, nose, TW, 0, nose, TW, 0, tail, TW, -CH*.7, tail]);
  pop(); blendMode(BLEND);
}

// ---- cached grain + vignette ---------------------------------------------------
if (!S.gv || S.gk !== width+'x'+height+'|'+sty){
  const g = createGraphics(width, height); g.colorMode(HSB,360,100,100,100); g.noStroke();
  const N = Math.min(9500, Math.floor(width*height/220));
  for (let i=0;i<N;i++){
    const px = Math.abs((Math.sin(i*12.9898)*43758.5453)%1)*width;
    const py = Math.abs((Math.sin(i*78.233+2.1)*43758.5453)%1)*height;
    g.fill(0,0, (i%2) ? 100 : 0, paper ? 8 : 6);
    g.rect(px, py, 1.7, 1.7);
  }
  for (let i=0;i<26;i++){ const s=i/26, bw=(1-s)*.10;
    g.fill(0,0,0, 1.2 + 4.0*s*s);
    g.rect(0,0,width,height*bw); g.rect(0,height*(1-bw),width,height*bw);
    g.rect(0,0,width*bw,height); g.rect(width*(1-bw),0,width*bw,height);
  }
  S.gv = g; S.gk = width+'x'+height+'|'+sty;
}
image(S.gv, 0, 0);
if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
